window.VeilGardeData.files["Tests-VeilGardeTrainingTests"] = {"group":"Tests-VeilGardeTrainingTests","files":[{"path":"Tests/VeilGardeTrainingTests/BackboneTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,121]],"header":{"lines":[1,11],"target":"VeilGardeTrainingTests","what":[6,10],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1409,"scopes":[["E","Backbone",null,"",19,19,[19,14],40,null,-1,0,"a",[]],["v","checkpoint",null,"static",21,21,[21,32],33,[20,20],0,0,"a"],["f","shipped",["_"],"static",36,36,[36,52],39,[35,35],0,0,"a"],["S","BackboneTests",null,"",42,43,[43,21],105,null,-1,0,"a"],["f","bicubic",[],"",44,45,[45,26],57,null,3,0,"a"],["f","renames",[],"",59,60,[60,19],66,null,3,0,"a"],["f","bake",[],"",68,69,[69,23],82,null,3,0,"a"],["f","importMatchesTheShippedFiles",[],"",84,85,[85,47],104,null,3,0,"a"],["X","TrainingMLXSuites",null,"",107,107,[107,28],121,null,-1,0,"a"],["S","BackboneOnGPU",null,"",108,109,[109,25],120,null,8,0,"a"],["f","xxsmall",[],"",112,112,[112,30],119,null,9,0,"a"]],"old":"","new":"//\n//  BackboneTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The DINOv2 import from Hugging Face's checkpoint: the bicubic resize equals PyTorch's\n//        bit for bit (bicubic_fixture.json); the rename map covers Dinov2ViT's 222 tensors; and,\n//        when this Mac has the checkpoint and the shipped files, small is byte-identical to the\n//        file Python exported, xsmall's tensors are byte-identical to Garde's, and (on the GPU)\n//        xxsmall's quantized tensors are byte-identical to Garde's.\n//\n\nimport Foundation\nimport Testing\nimport VeilGardeCore\nimport VeilGardeLens\n@testable import VeilGardeTraining\n\nenum Backbone {\n    /// The checkpoint the T9's hf/ cache holds (downloaded once with Python's hub client).\n    static var checkpoint: URL? {\n        let env = ProcessInfo.processInfo.environment\n        var candidates: [URL] = []\n        if let named = env[\"VEILGARDE_DINOV2_CHECKPOINT\"] { candidates.append(URL(fileURLWithPath: named)) }\n        if let area = WorkArea.resolve() {\n            let snapshots = area.root.appendingPathComponent(\"hf/hub/models--facebook--dinov2-small/snapshots\", isDirectory: true)\n            for name in (try? FileManager.default.contentsOfDirectory(atPath: snapshots.path))?.sorted() ?? [] {\n                candidates.append(snapshots.appendingPathComponent(\"\\(name)/model.safetensors\"))\n            }\n            candidates.append(area.root.appendingPathComponent(\"hf/models/facebook/dinov2-small/model.safetensors\"))\n        }\n        return candidates.first { FileManager.default.fileExists(atPath: $0.path) }\n    }\n\n    /// A shipped weight file, when this Mac has it.\n    static func shipped(_ file: WeightFile) -> URL? {\n        if let area = WorkArea.resolve() { WeightLocator.shared.register(area.weights) }\n        return WeightLocator.shared.url(file)\n    }\n}\n\n@Suite(\"Backbone: DINOv2 from Hugging Face's checkpoint\")\nstruct BackboneTests {\n    @Test(\"the bicubic resize is PyTorch's, bit for bit\")\n    func bicubic() throws {\n        let fixture = try Fixture.json(\"bicubic_fixture.json\")\n        let cases = fixture[\"cases\"] as! [[String: Any]]\n        #expect(cases.count == 3)\n        for c in cases {\n            let planes = Int(double(c[\"channels\"])), input = Int(double(c[\"in\"])), output = Int(double(c[\"out\"]))\n            let y = TorchBicubic.resize(floats(c[\"x\"]), planes: planes, input: input, output: output)\n            let expected = floats(c[\"y\"])\n            #expect(y.count == expected.count)\n            let differing = zip(y, expected).filter { $0.0.bitPattern != $0.1.bitPattern }.count\n            #expect(differing == 0, \"\\(input)→\\(output): \\(differing) of \\(y.count) values differ from torch\")\n        }\n    }\n\n    @Test(\"the rename map covers Dinov2ViT's tensors once each\")\n    func renames() {\n        let names = Dinov2Import.renames().map(\\.mlx) + [\"patch_embed.weight\", \"pos_embed\"]\n        #expect(names.count == 222)\n        #expect(Set(names).count == 222)\n        #expect(Set(Dinov2Import.renames().map(\\.hf)).count == 220)\n        #expect(names.contains(\"blocks.11.mlp.fc2.weight\") && names.contains(\"cls_token\") && names.contains(\"norm.bias\"))\n    }\n\n    @Test(\"the position bake keeps the CLS row and resizes the grid\")\n    func bake() throws {\n        // A 3×3 grid of 2 channels → 2×2, against the resize run directly.\n        let dim = 2, side = 3\n        var values: [Float] = [9, -9]\n        for p in 0..<(side * side) { for c in 0..<dim { values.append(Float(p * 10 + c)) } }\n        let baked = try Dinov2Import.bake(values, shape: [1, 1 + side * side, dim], to: 2)\n        #expect(baked.shape == [1, 5, 2])\n        #expect(Array(baked.values.prefix(2)) == [9, -9])\n        var planes = [Float](repeating: 0, count: dim * side * side)\n        for p in 0..<(side * side) { for c in 0..<dim { planes[c * side * side + p] = values[(1 + p) * dim + c] } }\n        let direct = TorchBicubic.resize(planes, planes: dim, input: side, output: 2)\n        for p in 0..<4 { for c in 0..<dim { #expect(baked.values[(1 + p) * dim + c] == direct[c * 4 + p]) } }\n        #expect(throws: VeilGardeFailure.self) { try Dinov2Import.bake(values, shape: [1, 9, dim]) }\n    }\n\n    @Test(\"small is byte-identical to the shipped export; xsmall's tensors are Garde's\", .enabled(if: Backbone.checkpoint != nil))\n    func importMatchesTheShippedFiles() throws {\n        let checkpoint = try #require(Backbone.checkpoint)\n        let tensors = try Dinov2Import.convert(try SafetensorsFile(url: checkpoint))\n        #expect(tensors.count == 222)\n        #expect(tensors[\"pos_embed\"]?.shape == [1, 257, 384])\n        #expect(tensors[\"patch_embed.weight\"]?.shape == [384, 14, 14, 3])\n        if let small = Backbone.shipped(.dinov2Small) {\n            let data = try Dinov2Import.encodeSmall(tensors)\n            let comparison = try Dinov2Import.compare(try SafetensorsFile(data: data), to: SafetensorsFile(url: small), referenceName: small.path)\n            #expect(comparison.problems.isEmpty, \"\\(comparison.problems)\")\n            #expect(comparison.identicalBytes == 222, \"max |Δ| \\(comparison.maxAbsDifference) at \\(comparison.worst ?? \"?\")\")\n            #expect(comparison.sameFile, \"the file is not byte-identical to \\(small.path)\")\n        }\n        if let xsmall = Backbone.shipped(.dinov2XSmall) {\n            let data = try Dinov2Import.encodeXSmall(tensors)\n            let comparison = try Dinov2Import.compare(try SafetensorsFile(data: data), to: SafetensorsFile(url: xsmall), referenceName: xsmall.path)\n            #expect(comparison.problems.isEmpty, \"\\(comparison.problems)\")\n            #expect(comparison.identicalBytes == 222, \"max |Δ| \\(comparison.maxAbsDifference) at \\(comparison.worst ?? \"?\")\")\n        }\n    }\n}\n\nextension TrainingMLXSuites {\n    @Suite(\"Backbone on the GPU\", .serialized)\n    struct BackboneOnGPU {\n        @Test(\"xxsmall quantized from xsmall is Garde's, tensor for tensor\",\n              .enabled(if: Backbone.shipped(.dinov2XSmall) != nil && Backbone.shipped(.dinov2XXSmall) != nil))\n        func xxsmall() throws {\n            let xsmall = try #require(Backbone.shipped(.dinov2XSmall)), reference = try #require(Backbone.shipped(.dinov2XXSmall))\n            let data = try Dinov2Import.encodeXXSmall(fromXSmall: xsmall)\n            let comparison = try Dinov2Import.compare(try SafetensorsFile(data: data), to: SafetensorsFile(url: reference), referenceName: reference.path)\n            #expect(comparison.tensors == 366)\n            #expect(comparison.problems.isEmpty, \"\\(comparison.problems.prefix(4))\")\n            #expect(comparison.identicalBytes == 366, \"max |Δ| \\(comparison.maxAbsDifference) at \\(comparison.worst ?? \"?\")\")\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/BoostTrainerTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,154]],"header":{"lines":[1,12],"target":"VeilGardeTrainingTests","what":[6,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1420,"scopes":[["S","BoostTrainerTests",null,"",20,21,[21,25],154,null,-1,0,"a"],["f","exactData",[],"static",22,22,[22,107],28,null,0,0,"a"],["f","exact",["_"],"",30,31,[31,38],69,null,0,0,"a"],["f","histData",[],"static",71,71,[71,109],76,null,0,0,"a"],["f","hist",[],"",78,79,[79,23],95,null,0,0,"a"],["f","warmStart",[],"",97,98,[98,28],114,null,0,0,"a"],["f","earlyStopping",[],"",116,117,[117,32],127,null,0,0,"a"],["f","frigateReadsIt",[],"",129,130,[130,33],145,null,0,0,"a"],["f","baseScore",[],"",147,148,[148,28],153,null,0,0,"a"]],"old":"","new":"//\n//  BoostTrainerTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The native trainer against xgboost 3.2. On integer features (so the bins are the values\n//        themselves) it grows XGBoost's trees: the same splits, children and node order, leaves\n//        and gains within float rounding, with weights, scale_pos_weight, γ, λ and\n//        min_child_weight. On continuous data it lands within ±0.005 AUC and ±0.01 log loss of\n//        xgboost's model, a warm start continues a model xgboost wrote without touching its\n//        trees, and every model it writes reads back through Frigate's evaluator unchanged.\n//\n\nimport Foundation\nimport Frigate\nimport Testing\nimport VeilGardeCore\n@testable import VeilGardeTraining\n\n@Suite(\"GBDT trainer\")\nstruct BoostTrainerTests {\n    static func exactData() throws -> (fixture: [String: Any], data: BoostDataset, weighted: BoostDataset) {\n        let fixture = try Fixture.json(\"boost_exact.json\")\n        let rows = fixture[\"X\"] as! [[NSNumber]]\n        let x = rows.flatMap { $0.map(\\.floatValue) }\n        let y = floats(fixture[\"y\"]), w = floats(fixture[\"w\"])\n        return (fixture, BoostDataset(x: x, y: y, features: 4), BoostDataset(x: x, y: y, weight: w, features: 4))\n    }\n\n    @Test(\"integer features: xgboost's trees, node for node\", arguments: [\"plain\", \"weighted_spw\", \"gamma_mcw_lambda\"])\n    func exact(_ name: String) throws {\n        let (fixture, plain, weighted) = try Self.exactData()\n        let c = (fixture[\"cases\"] as! [[String: Any]]).first { $0[\"name\"] as! String == name }!\n        let p = c[\"params\"] as! [String: Any]\n        var params = BoostParams(trees: c[\"rounds\"] as! Int, maxDepth: p[\"max_depth\"] as! Int, eta: double(p[\"eta\"]))\n        if let v = p[\"base_score\"] { params.baseScore = double(v) }\n        if let v = p[\"scale_pos_weight\"] { params.scalePosWeight = double(v) }\n        if let v = p[\"gamma\"] { params.gamma = double(v) }\n        if let v = p[\"min_child_weight\"] { params.minChildWeight = double(v) }\n        if let v = p[\"lambda\"] { params.lambda = double(v) }\n        let data = (c[\"weighted\"] as! Bool) ? weighted : plain\n        let result = BoostTrainer.train(data, params: params)\n        let model = result.model\n\n        let expectedBase = GBDTModel(trees: [], baseScoreProbability: 0.5, featureCount: 4)\n        var stored = expectedBase; stored.baseScore = c[\"base_score\"] as! String\n        #expect(abs(model.baseScoreProbability - stored.baseScoreProbability) <= 1e-6, \"\\(name): base_score \\(model.baseScore) vs \\(stored.baseScore)\")\n\n        let trees = c[\"trees\"] as! [[String: Any]]\n        #expect(model.trees.count == trees.count)\n        for (k, (mine, theirs)) in zip(model.trees, trees).enumerated() {\n            #expect(mine.leftChildren.map(Int.init) == ints(theirs[\"left_children\"]), \"\\(name) tree \\(k): left\")\n            #expect(mine.rightChildren.map(Int.init) == ints(theirs[\"right_children\"]), \"\\(name) tree \\(k): right\")\n            #expect(mine.parents.map(Int.init) == ints(theirs[\"parents\"]), \"\\(name) tree \\(k): parents\")\n            #expect(mine.splitIndices.map(Int.init) == ints(theirs[\"split_indices\"]), \"\\(name) tree \\(k): split features\")\n            #expect(mine.defaultLeft == ints(theirs[\"default_left\"]), \"\\(name) tree \\(k): default_left\")\n            let conditions = floats(theirs[\"split_conditions\"]), weights = floats(theirs[\"base_weights\"])\n            let losses = floats(theirs[\"loss_changes\"]), hessians = floats(theirs[\"sum_hessian\"])\n            for i in 0..<min(mine.nodeCount, conditions.count) {\n                #expect(abs(mine.splitConditions[i] - conditions[i]) <= 1e-5 * max(1, abs(conditions[i])), \"\\(name) tree \\(k) node \\(i): condition\")\n                #expect(abs(mine.baseWeights[i] - weights[i]) <= 1e-5 * max(1, abs(weights[i])), \"\\(name) tree \\(k) node \\(i): weight\")\n                #expect(abs(mine.lossChanges[i] - losses[i]) <= 1e-4 * max(1, abs(losses[i])), \"\\(name) tree \\(k) node \\(i): loss change\")\n                #expect(abs(mine.sumHessian[i] - hessians[i]) <= 1e-4 * max(1, abs(hessians[i])), \"\\(name) tree \\(k) node \\(i): hessian\")\n            }\n        }\n        let margins = floats(c[\"margin\"])\n        let worst = (0..<data.count).map { abs(model.margin(data.row($0)) - margins[$0]) }.max() ?? 0\n        #expect(worst <= 1e-4, \"\\(name): margins differ by \\(worst)\")\n    }\n\n    static func histData() throws -> (train: BoostDataset, validation: BoostDataset, fixture: [String: Any]) {\n        let t = try Fixture.tensors(\"boost_hist.safetensors\")\n        return (BoostDataset(x: try t.float32(\"x_train\"), y: try t.float32(\"y_train\"), features: 8),\n                BoostDataset(x: try t.float32(\"x_val\"), y: try t.float32(\"y_val\"), features: 8),\n                try Fixture.json(\"boost_hist.json\"))\n    }\n\n    @Test(\"continuous features: within ±0.005 AUC and ±0.01 log loss of xgboost\")\n    func hist() throws {\n        let (train, validation, fixture) = try Self.histData()\n        let result = BoostTrainer.train(train, validation: validation, params: BoostParams(trees: 60, maxDepth: 4, eta: 0.1))\n        let p = (0..<validation.count).map { result.model.predict(validation.row($0)) }\n        let auc = Metrics.auc(p, validation.y), loss = Metrics.logloss(p, validation.y)\n        #expect(abs(auc - double(fixture[\"val_auc\"])) <= 0.005, \"AUC \\(auc) vs xgboost \\(double(fixture[\"val_auc\"]))\")\n        #expect(abs(loss - double(fixture[\"val_logloss\"])) <= 0.01, \"log loss \\(loss) vs xgboost \\(double(fixture[\"val_logloss\"]))\")\n        #expect(result.rounds.count == 60)\n        #expect(abs(result.rounds.last!.validation! - auc) < 1e-12)\n\n        let sampled = fixture[\"sampled\"] as! [String: Any]\n        let s = BoostTrainer.train(train, validation: validation, params: BoostParams(trees: 60, maxDepth: 4, eta: 0.1, subsample: 0.8, colsampleByTree: 0.75, seed: 3))\n        let ps = (0..<validation.count).map { s.model.predict(validation.row($0)) }\n        #expect(abs(Metrics.auc(ps, validation.y) - double(sampled[\"val_auc\"])) <= 0.01)\n        let again = BoostTrainer.train(train, validation: validation, params: BoostParams(trees: 60, maxDepth: 4, eta: 0.1, subsample: 0.8, colsampleByTree: 0.75, seed: 3))\n        #expect(again.model.encodeXGBoostJSON() == s.model.encodeXGBoostJSON(), \"a seed names one model\")\n    }\n\n    @Test(\"a warm start appends to xgboost's model and keeps its trees byte for byte\")\n    func warmStart() throws {\n        let (train, validation, fixture) = try Self.histData()\n        let warm = fixture[\"warm\"] as! [String: Any]\n        let text = warm[\"model30\"] as! String\n        let parent = try GBDTModel.decode(xgboostJSON: Data(text.utf8))\n        #expect(parent.trees.count == 30)\n        let result = BoostTrainer.train(train, validation: validation, params: BoostParams(trees: 10, maxDepth: 4, eta: 0.1), warmStart: parent)\n        #expect(result.model.trees.count == 40)\n        #expect(result.inheritedTrees == 30)\n        #expect(result.model.baseScore == parent.baseScore)\n        for i in 0..<30 { #expect(result.model.trees[i].raw == parent.trees[i].raw) }\n        #expect(Array(result.model.trees[30...].map(\\.id)) == Array(30..<40))\n        let encoded = String(decoding: result.model.encodeXGBoostJSON(), as: UTF8.self)\n        for tree in parent.trees { #expect(encoded.contains(tree.raw!)) }\n        let p = (0..<validation.count).map { result.model.predict(validation.row($0)) }\n        #expect(abs(Metrics.auc(p, validation.y) - double(warm[\"val_auc40\"])) <= 0.005)\n    }\n\n    @Test(\"early stopping keeps the best round and truncates to it\")\n    func earlyStopping() throws {\n        let (train, validation, _) = try Self.histData()\n        let result = BoostTrainer.train(train, validation: validation, params: BoostParams(trees: 400, maxDepth: 6, eta: 0.3, earlyStoppingRounds: 5))\n        let best = try #require(result.bestTreeCount)\n        #expect(result.model.trees.count == best)\n        #expect(result.rounds.count < 400)\n        let scores = result.rounds.compactMap(\\.validation)\n        let top = scores.max()!\n        #expect(abs(scores[best - 1] - top) < 1e-15)\n        #expect(scores.firstIndex(of: top)! == best - 1, \"the first best round wins\")\n    }\n\n    @Test(\"a trained model reads back through Frigate's evaluator with identical predictions\")\n    func frigateReadsIt() throws {\n        let (train, validation, _) = try Self.histData()\n        let result = BoostTrainer.train(train, params: BoostParams(trees: 25, maxDepth: 5, eta: 0.2, subsample: 0.9, colsampleByTree: 0.8, seed: 1))\n        let json = result.model.encodeXGBoostJSON()\n        let file = FileManager.default.temporaryDirectory.appendingPathComponent(\"vg-trained-\\(UUID().uuidString).json\")\n        try json.write(to: file)\n        defer { try? FileManager.default.removeItem(at: file) }\n        let frigate = try XGBoostTreeModel(url: file)\n        #expect(frigate.numFeatures == 8)\n        let decoded = try GBDTModel.decode(xgboostJSON: json)\n        #expect(decoded.encodeXGBoostJSON() == json, \"decode → encode is the identity on a trained model\")\n        for i in 0..<validation.count {\n            let row = validation.row(i)\n            #expect(frigate.predict(row) == result.model.predict(row))\n        }\n    }\n\n    @Test(\"base_score: the weighted mean at scale_pos_weight 1, a Newton step otherwise\")\n    func baseScore() throws {\n        let (_, plain, weighted) = try Self.exactData()\n        let mean = Double(zip(weighted.y, weighted.weight!).map { Double($0) * Double($1) }.reduce(0, +)) / weighted.weight!.map(Double.init).reduce(0, +)\n        #expect(abs(BoostTrainer.baseScore(weighted, scalePosWeight: 1) - mean) < 1e-12)\n        #expect(BoostTrainer.baseScore(plain, scalePosWeight: 1) == Double(plain.y.reduce(0, +)) / Double(plain.count))\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/CombinerTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,106]],"header":{"lines":[1,12],"target":"VeilGardeTrainingTests","what":[6,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1429,"scopes":[["S","CombinerTests",null,"",19,20,[20,21],106,null,-1,0,"a"],["f","fixture",[],"static",21,21,[21,50],21,null,0,8,"a"],["f","optional",["_"],"static",23,23,[23,49],23,null,0,8,"a"],["f","features",[],"",25,26,[26,27],40,null,0,0,"a"],["f","file",[],"",42,43,[43,23],53,null,0,0,"a"],["f","fit",[],"",55,56,[56,22],68,null,0,0,"a"],["f","expectedRescue",["w0","w","settings"],"",72,72,[72,87],80,[70,71],0,0,"a"],["f","sweep",[],"",82,83,[83,24],95,null,0,0,"a"],["f","sweepShipped",[],"",97,98,[98,31],105,null,0,0,"a"]],"old":"","new":"//\n//  CombinerTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The combiner's five columns equal the reference's first five (atlas_combiner.features;\n//        the sixth, the noiseprint's, left on 2026-10-21) wherever the art-pair head did not move\n//        the art logit, the bounded solver reaches scipy's optimum on the reference fit, the\n//        rescue sweep follows its rule, on the shipped combiner's own weights no candidate passes,\n//        so the sweep falls back to the shipped 1.0, and a fit writes the version-1 file keyed by\n//        member.\n//\n\nimport Foundation\nimport Testing\nimport VeilGardeCore\n@testable import VeilGardeTraining\n\n@Suite(\"Stack combiner\")\nstruct CombinerTests {\n    static func fixture() throws -> [String: Any] { try Fixture.json(\"combiner_fixture.json\") }\n\n    static func optional(_ any: Any?) -> Double? { (any as? NSNumber)?.doubleValue }\n\n    @Test(\"the five feature columns equal the reference's first five where no art-pair moved the art logit\")\n    func features() throws {\n        let f = try Self.fixture()\n        let base = doubles(f[\"base\"]), heads = (f[\"heads\"] as! [[NSNumber]]).map { $0.map(\\.doubleValue) }\n        let pair = (f[\"pair\"] as! [Any]).map(Self.optional)\n        let expected = (f[\"features\"] as! [[NSNumber]]).map { $0.map(\\.doubleValue) }\n        var checked = 0\n        for i in base.indices {\n            if let p = pair[i], CombinerFeatures.logit(p, cap: CombinerFeatures.capHead) < CombinerFeatures.logit(heads[i][0], cap: CombinerFeatures.capHead) { continue }\n            checked += 1\n            let row = CombinerFeatures.row(camera: base[i], heads: heads[i])\n            #expect(row.count == CombinerFeatures.count && CombinerFeatures.count == 5)\n            #expect(maxAbs(row, Array(expected[i].prefix(5))) < 1e-12, \"row \\(i)\")\n        }\n        #expect(checked > 500)\n    }\n\n    @Test(\"a fit writes the version-1 file: the camera anchor, the evidence keyed by member\")\n    func file() throws {\n        let f = try Self.fixture()\n        let base = doubles(f[\"base\"]), heads = (f[\"heads\"] as! [[NSNumber]]).map { $0.map(\\.doubleValue) }, y = ints(f[\"y\"])\n        let samples = base.indices.map { CombinerSample(id: \"row\\($0)\", label: y[$0], camera: base[$0], heads: heads[$0]) }\n        let (file, report) = try CombinerTrainer.train(samples)\n        #expect(file.version == 1 && file.evidence.map(\\.member) == [\"art\", \"blur\", \"human\"] && file.anchor.cap == 4 && file.evidenceCap == 2)\n        #expect(file.anchor.w >= 0 && file.evidence.allSatisfy { $0.w >= 0 } && file.rescue.w == report.rescue)\n        #expect(report.fitted.count == 1 + CombinerFeatures.count && report.testAUCCamera != nil)\n        let c = try file.combiner()\n        #expect(c.evidenceMembers == [\"art\", \"blur\", \"human\"])\n    }\n\n    @Test(\"the bounded solver reaches scipy's optimum on the reference's six-column fit\")\n    func fit() throws {\n        let f = try Self.fixture()\n        let features = (f[\"features\"] as! [[NSNumber]]).map { $0.map(\\.doubleValue) }\n        let y = ints(f[\"y\"]), n = f[\"train\"] as! Int\n        var flat = [Double]()\n        for row in features.prefix(n) { var r = row; r[4] = 0; flat += r }\n        let theta = BoundedLogistic.fit(f: flat, y: y.prefix(n).map(Double.init), m: 6, sampleWeight: y.prefix(n).map { $0 == 0 ? 3 : 1 })\n        let tight = f[\"tight\"] as! [String: Any]\n        let tw = doubles(tight[\"w\"])\n        #expect(abs(theta[0] - double(tight[\"w0\"])) < 1e-4)\n        for j in [0, 1, 2, 3, 5] { #expect(abs(theta[1 + j] - tw[j]) < 1e-4, \"w[\\(j)] \\(theta[1 + j]) vs \\(tw[j])\") }\n        #expect(theta.dropFirst().allSatisfy { $0 >= 0 })\n    }\n\n    /// The sweep's rule, restated: the first nonzero candidate under which every probe reads at or\n    /// under 0.5 and none above 0.42, else the fallback.\n    func expectedRescue(w0: Double, w: [Double], settings: CombinerSettings) -> Double {\n        for candidate in settings.rescueSweep where candidate != 0 {\n            var ww = w\n            ww[4] = candidate\n            let scores = CombinerTrainer.probeScores(w0, ww, settings.probes)\n            if scores.values.allSatisfy({ $0 <= 0.5 }) && (scores.values.max() ?? 0) <= settings.maxProbe { return candidate }\n        }\n        return settings.rescueFallback\n    }\n\n    @Test(\"the rescue sweep follows its rule on the reference fit and on the research's weights\")\n    func sweep() throws {\n        let f = try Self.fixture()\n        let final = f[\"final\"] as! [String: Any]\n        var fitted = Array(doubles(final[\"w\"]).prefix(5))\n        fitted[4] = 0\n        let settings = CombinerSettings()\n        #expect(CombinerTrainer.chooseRescue(w0: double(final[\"w0\"]), w: fitted, settings: settings).rescue\n                == expectedRescue(w0: double(final[\"w0\"]), w: fitted, settings: settings))\n        // The research's v1.9.7 weights without the noiseprint: probe 3 reads 0.409 at rescue 0.5, under the 0.42 bar.\n        let research = [3.8205217946638634, 0.0, 0.0, 0.1966929563436263, 0.0]\n        let (rescue, rows) = CombinerTrainer.chooseRescue(w0: -0.6754975033517225, w: research, settings: settings)\n        #expect(rescue == 0.5 && rows.count == settings.rescueSweep.count)\n    }\n\n    @Test(\"on the shipped combiner's own weights no sweep candidate passes, and the fallback is the shipped rescue\")\n    func sweepShipped() throws {\n        let c = try StackCombiner.load(Fixture.resource(\"stack_combiner.json\"))\n        let w = [Double(c.anchor.w)] + c.evidence.map { Double($0.w) } + [0]\n        let settings = CombinerSettings()\n        let (rescue, sweep) = CombinerTrainer.chooseRescue(w0: Double(c.w0), w: w, settings: settings)\n        #expect(!sweep.contains { $0.probesReal == settings.probes.count && $0.maxProbe <= settings.maxProbe })\n        #expect(rescue == settings.rescueFallback && rescue == Double(c.rescue.w))\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/EngineTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,123]],"header":{"lines":[1,12],"target":"VeilGardeTrainingTests","what":[6,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1438,"scopes":[["S","EngineTests",null,"",19,20,[20,19],123,null,-1,0,"a"],["f","recipe",["id"],"",21,21,[21,54],27,null,0,0,"a"],["f","plan",[],"",29,30,[30,23],41,null,0,0,"a"],["f","refusals",[],"",43,44,[44,27],55,null,0,0,"a"],["f","train",[],"",57,58,[58,24],98,null,0,0,"a"],["f","warmStart",[],"",100,101,[101,28],111,null,0,0,"a"],["f","widthRefused",[],"",113,114,[114,31],122,null,0,0,"a"]],"old":"","new":"//\n//  EngineTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: A whole recipe through the engine on a synthetic work area: the plan reads without\n//        training, a refusal stops the run before a candidate exists, and the run writes a\n//        candidate bundle that verifies, whose camera head is a from-scratch fit over the 393-column\n//        camera row with its evaluation twin reported, and whose heads and combiner load as the\n//        detector loads them. A warm start keeps the parent's trees byte for byte; a parent of\n//        another width cannot be warm-started.\n//\n\nimport Foundation\nimport Testing\nimport VeilGardeCore\n@testable import VeilGardeTraining\n\n@Suite(\"Training engine\", .serialized)\nstruct EngineTests {\n    func recipe(id: String = \"toy\") -> TrainingRecipe {\n        TrainingRecipe(id: id) {\n            Combiner()\n            CameraHead().scratch(trees: 12, eta: 0.1)\n            for kind in [HeadKind.art, .blur, .human, .preview] { SpecialistHead(kind) }\n        }\n    }\n\n    @Test(\"the plan names every member in dependency order and touches nothing\")\n    func plan() throws {\n        let s = try SyntheticArea.make()\n        defer { s.remove() }\n        let engine = TrainingEngine(area: s.area, parent: s.parent, store: s.store)\n        let plan = try engine.plan(recipe())\n        #expect(plan.refusals.isEmpty, \"\\(plan.refusals)\")\n        #expect(plan.models.map(\\.model) == [\"camera\", \"head:art\", \"head:blur\", \"head:human\", \"head:preview\", \"combiner\"])\n        #expect(plan.summary.contains(\"from scratch: 12 trees\"))\n        #expect(plan.summary.contains(\"393 columns\"))\n        #expect(plan.summary.contains(\"the anchor from the camera head this recipe trains\"))\n        #expect(!FileManager.default.fileExists(atPath: plan.candidate.path))\n    }\n\n    @Test(\"a refusal stops the run before a candidate exists\")\n    func refusals() throws {\n        let s = try SyntheticArea.make()\n        defer { s.remove() }\n        let engine = TrainingEngine(area: s.area, parent: s.parent, store: s.store)\n        let bad = TrainingRecipe(id: \"bad\") { SpecialistHead(.semtile) }\n        let plan = try engine.plan(bad)\n        #expect(plan.refusals.count == 1, \"semtile has no tokens in the store\")\n        #expect(throws: VeilGardeFailure.self) { try engine.train(bad) }\n        #expect(!FileManager.default.fileExists(atPath: plan.candidate.path))\n        #expect(throws: VeilGardeFailure.self) { try engine.plan(TrainingRecipe(id: \"a/b\") { Combiner() }) }\n        #expect(throws: VeilGardeFailure.self, \"a member named twice\") { try engine.plan(TrainingRecipe(id: \"twice\") { Combiner(); Combiner() }) }\n    }\n\n    @Test(\"a full recipe writes a candidate bundle the detector can load\")\n    func train() throws {\n        let s = try SyntheticArea.make()\n        defer { s.remove() }\n        var lines: [String] = []\n        let engine = TrainingEngine(area: s.area, parent: s.parent, store: s.store) { if let l = $0.line { lines.append(l) } }\n        let outcome = try engine.train(recipe())\n        let c = outcome.candidate\n        try c.verify()\n        let parent = try ModelBundle.load(s.parent)\n\n        // The camera head: a scratch fit over the 393 columns, no parent, the evaluation twin reported.\n        let camera = try #require(c.manifest.artifact(.camera))\n        #expect(camera.parent == nil && camera.file == \"camera/camera.xgb.json\")\n        let head = try GBDTModel.load(c.url(.camera)!)\n        #expect(head.trees.count == 12 && head.featureCount == CameraRow.width)\n        let metrics = try JSONSerialization.jsonObject(with: Data(contentsOf: c.root.appendingPathComponent(\"camera/metrics.json\"))) as! [String: Any]\n        let report = try #require(metrics[\"report\"] as? [String: Any])\n        #expect((report[\"evaluationRows\"] as? Int ?? 0) > 0 && report[\"evaluationAUC\"] is Double)\n        #expect(report[\"parentComparable\"] as? Bool == true, \"the shipped head reads the same 393 columns\")\n\n        // Heads and the combiner load as the detector loads them.\n        for kind in [HeadKind.art, .blur, .human, .preview] {\n            let url = try #require(c.url(.head, head: kind))\n            #expect(url.path.hasSuffix(\"heads/\\(kind.rawValue)/head.json\"))\n            #expect(try LinearHead.load(url).coef.count == 384)\n        }\n        let combiner = try StackCombiner.load(c.url(.combiner)!)\n        #expect(combiner.anchor.w >= 0 && combiner.evidenceMembers == [\"art\", \"blur\", \"human\"] && combiner.version == 1)\n        #expect(c.manifest.artifact(.combiner)?.file == \"combiner/stack_combiner.json\")\n        // What the recipe did not name is the parent's, byte for byte.\n        #expect(c.manifest.artifact(.head, head: .screenshot)?.sha256 == parent.sha256(.head, head: .screenshot))\n        #expect(c.manifest.weights == parent.manifest.weights)\n        // The record of the run.\n        let runs = try String(contentsOf: c.root.appendingPathComponent(\"runs.jsonl\"), encoding: .utf8).split(separator: \"\\n\")\n        #expect(runs.count > 10)\n        #expect(lines.contains { $0.hasPrefix(\"candidate toy verified\") })\n        #expect(outcome.metrics.keys.sorted() == [\"camera\", \"combiner\", \"head:art\", \"head:blur\", \"head:human\", \"head:preview\"])\n        #expect(try JSONDecoder().decode(TrainingRecipe.self, from: Data(contentsOf: c.root.appendingPathComponent(\"recipe.json\"))) == recipe())\n        // A second run under the same id is refused.\n        #expect(throws: VeilGardeFailure.self) { try engine.train(recipe()) }\n    }\n\n    @Test(\"a warm start keeps the parent's trees byte for byte and records the parent\")\n    func warmStart() throws {\n        let s = try SyntheticArea.make()\n        defer { s.remove() }\n        let engine = TrainingEngine(area: s.area, parent: s.parent, store: s.store)\n        let c = try engine.train(TrainingRecipe(id: \"warm\") { CameraHead().warmStart(add: 3, eta: 0.03) }).candidate\n        let parent = try ModelBundle.load(s.parent)\n        #expect(c.manifest.artifact(.camera)?.parent == parent.sha256(.camera))\n        let head = try GBDTModel.load(c.url(.camera)!), before = try GBDTModel.load(parent.url(.camera)!)\n        #expect(head.trees.count == before.trees.count + 3)\n        for i in 0..<before.trees.count { #expect(head.trees[i].raw == before.trees[i].raw) }\n    }\n\n    @Test(\"a parent of another width cannot be warm-started\")\n    func widthRefused() throws {\n        let s = try SyntheticArea.make()\n        defer { s.remove() }\n        let dataset = try CameraDataset.assemble(FeatureStore(directory: s.store), settings: CameraSettings())\n        var settings = CameraSettings()\n        settings.mode = .warmStart(add: 2, eta: 0.03)\n        let narrow = GBDTModel(trees: [], baseScoreProbability: 0.5, featureCount: 5)\n        #expect(throws: VeilGardeFailure.self) { try CameraTrainer.train(dataset, settings: settings, parent: narrow) }\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/Fixture.swift","status":"added","lang":"swift","hunks":[[1,0,1,38]],"header":{"lines":[1,8],"target":"VeilGardeTrainingTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1445,"scopes":[["E","Fixture",null,"",13,13,[13,13],32,null,-1,0,"a",[]],["f","resource",["_"],"static",22,22,[22,48],22,null,0,8,"a"],["f","url",["_"],"static",24,24,[24,43],24,null,0,8,"a"],["f","json",["_"],"static",26,26,[26,61],28,null,0,0,"a"],["f","tensors",["_"],"static",30,30,[30,66],30,null,0,8,"a"],["f","floats",["_"],"",34,34,[34,36],34,null,-1,8,"a"],["f","doubles",["_"],"",35,35,[35,38],35,null,-1,8,"a"],["f","ints",["_"],"",36,36,[36,32],36,null,-1,8,"a"],["f","double",["_"],"",37,37,[37,35],37,null,-1,8,"a"],["f","maxAbs",["_","_"],"",38,38,[38,52],38,null,-1,8,"a"]],"old":"","new":"//\n//  Fixture.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Paths the training tests read: their committed fixtures (written once from the Python\n//        reference) and the shipped bundle's resources, by repo path.\n//\n\nimport Foundation\nimport VeilGardeCore\n\nenum Fixture {\n    static let repoRoot: URL = {\n        var url = URL(fileURLWithPath: #filePath)\n        while url.lastPathComponent != \"Tests\" { url.deleteLastPathComponent() }\n        return url.deletingLastPathComponent()\n    }()\n\n    static let resources = repoRoot.appendingPathComponent(\"Sources/VeilGardeInference/Resources\")\n\n    static func resource(_ name: String) -> URL { resources.appendingPathComponent(name) }\n\n    static func url(_ name: String) -> URL { repoRoot.appendingPathComponent(\"Tests/VeilGardeTrainingTests/Fixtures/\\(name)\") }\n\n    static func json(_ name: String) throws -> [String: Any] {\n        try JSONSerialization.jsonObject(with: Data(contentsOf: url(name))) as! [String: Any]\n    }\n\n    static func tensors(_ name: String) throws -> SafetensorsFile { try SafetensorsFile(url: url(name)) }\n\n}\n\nfunc floats(_ any: Any?) -> [Float] { (any as? [NSNumber])?.map { $0.floatValue } ?? [] }\nfunc doubles(_ any: Any?) -> [Double] { (any as? [NSNumber])?.map { $0.doubleValue } ?? [] }\nfunc ints(_ any: Any?) -> [Int] { (any as? [NSNumber])?.map { $0.intValue } ?? [] }\nfunc double(_ any: Any?) -> Double { (any as? NSNumber)?.doubleValue ?? .nan }\nfunc maxAbs(_ a: [Double], _ b: [Double]) -> Double { zip(a, b).map { abs($0 - $1) }.max() ?? 0 }\n"},{"path":"Tests/VeilGardeTrainingTests/LinkTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,15]],"header":{"lines":[1,7],"target":"VeilGardeTrainingTests","what":[6,6],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1455,"scopes":[["S","TrainingLinkTests",null,"",12,13,[13,25],15,null,-1,0,"a"],["f","reExportsCore",[],"",14,14,[14,31],14,null,0,8,"a"]],"old":"","new":"//\n//  LinkTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The module links and re-exports the layers below it.\n//\n\nimport Testing\nimport VeilGardeTraining\n\n@Suite(\"Training links\")\nstruct TrainingLinkTests {\n    @Test func reExportsCore() { #expect(!VeilGardeVersion.string.isEmpty) }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/LogisticTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,37]],"header":{"lines":[1,9],"target":"VeilGardeTrainingTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1457,"scopes":[["S","LogisticTests",null,"",15,16,[16,21],37,null,-1,0,"a"],["f","heads",["_"],"",17,18,[18,38],36,null,0,0,"a"]],"old":"","new":"//\n//  LogisticTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The sklearn-parity solvers. StandardScaler + LogisticNewton reach sklearn's optimum for\n//        the three head recipes (balanced C 0.5, unweighted C 0.5, unweighted C 1) within 1e-5,\n//        and sit within 2e-3 of the reference fits made at lbfgs's default tolerance.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeTraining\n\n@Suite(\"Logistic solvers\")\nstruct LogisticTests {\n    @Test(\"the head recipes reach sklearn's optimum\", arguments: [\"balanced_c05\", \"none_c05\", \"none_c1\"])\n    func heads(_ name: String) throws {\n        let t = try Fixture.tensors(\"lr_fixture.safetensors\")\n        let x = try t.float32(\"x\"), y = try t.float32(\"y\").map(Double.init)\n        let d = 48, n = y.count\n        let c = (try Fixture.json(\"lr_fixture.json\")[\"cases\"] as! [[String: Any]]).first { $0[\"name\"] as! String == name }!\n        let all = Array(0..<n)\n        let scaler = StandardScaler.fit(x, d: d, rows: all)\n        #expect(maxAbs(scaler.mean, doubles(c[\"mean\"])) < 1e-9)\n        #expect(maxAbs(scaler.scale, doubles(c[\"scale\"])) < 1e-9)\n        #expect(scaler.scale[5] == 1)\n        let z = scaler.transform(x, d: d, rows: all)\n        let fit = LogisticNewton.fit(x: z, y: y, d: d, C: double(c[\"C\"]), classWeight: c[\"class_weight\"] as! String == \"balanced\" ? .balanced : .none)\n        #expect(maxAbs(fit.coef, doubles(c[\"coef\"])) < 1e-5, \"\\(name): coef\")\n        #expect(abs(fit.intercept - double(c[\"intercept\"])) < 1e-5, \"\\(name): intercept\")\n        #expect(maxAbs(fit.coef, doubles(c[\"reference_coef\"])) < 2e-3, \"\\(name): distance to the reference lbfgs fit\")\n        let p = (0..<n).map { fit.probability(z[($0 * d)..<(($0 + 1) * d)]) }\n        #expect(maxAbs(p, doubles(c[\"p\"])) < 1e-6)\n        #expect(fit.coef[5] == 0)\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/MLXGate.swift","status":"added","lang":"swift","hunks":[[1,0,1,21]],"header":{"lines":[1,10],"target":"VeilGardeTrainingTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1459,"scopes":[["S","TrainingMLXSuites",null,"",20,21,[21,25],21,null,-1,8,"a"]],"old":"","new":"//\n//  MLXGate.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The MLX suites run one at a time and only when asked: VEILGARDE_MLX_TESTS=1 (or\n//        FRIGATE_MLX_TESTS=1). Every GPU suite in this target nests under TrainingMLXSuites, which\n//        is serialized; run the targets with `swift test --no-parallel` too, so two MLX workloads\n//        never overlap.\n//\n\nimport Foundation\nimport Testing\n\nlet mlxTests: Bool = {\n    let env = ProcessInfo.processInfo.environment\n    return env[\"VEILGARDE_MLX_TESTS\"] == \"1\" || env[\"FRIGATE_MLX_TESTS\"] == \"1\"\n}()\n\n@Suite(\"Training: MLX, one suite at a time\", .enabled(if: mlxTests), .serialized)\nstruct TrainingMLXSuites {}\n"},{"path":"Tests/VeilGardeTrainingTests/MetricsTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,34]],"header":{"lines":[1,7],"target":"VeilGardeTrainingTests","what":[6,6],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1460,"scopes":[["S","MetricsTests",null,"",13,14,[14,20],34,null,-1,0,"a"],["f","sklearn",[],"",15,16,[16,26],24,null,0,0,"a"],["f","edges",[],"",26,27,[27,17],33,null,0,0,"a"]],"old":"","new":"//\n//  MetricsTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: AUC (ties averaged, weighted or not) and log loss equal sklearn's on a tied score.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeTraining\n\n@Suite(\"Metrics\")\nstruct MetricsTests {\n    @Test(\"AUC and log loss equal sklearn's, ties and weights included\")\n    func sklearn() throws {\n        let fixture = try Fixture.json(\"boost_hist.json\")\n        let m = fixture[\"metrics\"] as! [String: Any]\n        let p = floats(m[\"p\"]), w = floats(m[\"w\"])\n        let y = try Fixture.tensors(\"boost_hist.safetensors\").float32(\"y_val\")\n        #expect(abs(Metrics.auc(p, y) - double(m[\"auc\"])) < 1e-12)\n        #expect(abs(Metrics.auc(p, y, weights: w) - double(m[\"auc_weighted\"])) < 1e-9)\n        #expect(abs(Metrics.logloss(p, y) - double(m[\"logloss\"])) < 1e-9)\n    }\n\n    @Test(\"a missing class gives NaN; the operating point counts the band as inconclusive\")\n    func edges() {\n        #expect(Metrics.auc([0.1, 0.2], [1, 1]).isNaN)\n        let op = Metrics.operatingPoint([0.1, 0.55, 0.9, 0.7], [0, 0, 1, 0], threshold: 0.56, band: 0.04)\n        #expect(op.inconclusiveRate == 0.25)\n        #expect(op.realFalsePositiveRate == 1.0 / 3.0)\n        #expect(op.generatedRecall == 1)\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/PythonRandomTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,38]],"header":{"lines":[1,8],"target":"VeilGardeTrainingTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1463,"scopes":[["S","PythonRandomTests",null,"",14,15,[15,25],38,null,-1,0,"a"],["f","sequences",[],"",16,17,[17,28],37,null,0,0,"a"]],"old":"","new":"//\n//  PythonRandomTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The CPython `random.Random` port draws Python's exact sequences: 32- and 64-bit words,\n//        random(), randrange and shuffle, for small and multi-word seeds.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeTraining\n\n@Suite(\"CPython random\")\nstruct PythonRandomTests {\n    @Test(\"every recorded sequence matches CPython 3.12\")\n    func sequences() throws {\n        let cases = try Fixture.json(\"python_random.json\")[\"cases\"] as! [[String: Any]]\n        #expect(cases.count == 5)\n        for c in cases {\n            let seed = UInt64(c[\"seed\"] as! String)!\n            var r = PythonRandom(seed: seed)\n            #expect((0..<6).map { _ in Int(r.getrandbits(32)) } == ints(c[\"bits32\"]), \"seed \\(seed)\")\n            r = PythonRandom(seed: seed)\n            #expect((0..<6).map { _ in r.random() } == doubles(c[\"random\"]), \"seed \\(seed)\")\n            r = PythonRandom(seed: seed)\n            var a = Array(0..<10), b = Array(0..<37)\n            r.shuffle(&a); r.shuffle(&b)\n            #expect(a == ints(c[\"shuffle10\"]), \"seed \\(seed)\")\n            #expect(b == ints(c[\"shuffle37\"]), \"seed \\(seed)\")\n            r = PythonRandom(seed: seed)\n            let bounds = (c[\"randbelow_n\"] as! [String]).map { Int($0)! }\n            #expect(bounds.map { r.randbelow($0) } == (c[\"randbelow\"] as! [String]).map { Int($0)! }, \"seed \\(seed)\")\n            r = PythonRandom(seed: seed)\n            #expect((0..<3).map { _ in r.getrandbits(64) } == (c[\"bits64\"] as! [String]).map { UInt64($0)! }, \"seed \\(seed)\")\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/RecipeTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,85]],"header":{"lines":[1,10],"target":"VeilGardeTrainingTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1465,"scopes":[["S","RecipeTests",null,"",17,18,[18,19],85,null,-1,0,"a"],["f","builder",[],"",19,20,[20,26],42,null,0,0,"a"],["f","shipped",[],"",44,45,[45,26],52,null,0,0,"a"],["f","toml",[],"",54,55,[55,23],84,null,0,0,"a"]],"old":"","new":"//\n//  RecipeTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The recipe DSL: the builder takes `if` and `for`, modifiers return changed copies, the\n//        engine's order is the dependency order (the camera head, the heads, the combiner), recipes\n//        round-trip as JSON through their members' kinds, and recipe.toml reads into the same\n//        values, refusing what it does not know (the fusion table and its columns among it).\n//\n\nimport Foundation\nimport Testing\nimport VeilGardeCore\n@testable import VeilGardeTraining\n\n@Suite(\"Training recipes\")\nstruct RecipeTests {\n    @Test(\"the builder, the modifiers and the dependency order\")\n    func builder() throws {\n        let withPreview = true\n        let recipe = TrainingRecipe(id: \"r\") {\n            Combiner().realsWeight(2)\n            for kind in [HeadKind.art, .blur] { SpecialistHead(kind).regularization(C: 0.25) }\n            if withPreview { SpecialistHead(.preview) }\n            CameraHead().warmStart(add: 10)\n        }\n        #expect(recipe.ordered.map(\\.name) == [\"camera\", \"head:art\", \"head:blur\", \"head:preview\", \"combiner\"])\n        let camera = try #require(recipe.ordered[0] as? CameraHead)\n        #expect(camera.settings.mode == .warmStart(add: 10, eta: 0.03))\n        let preview = try #require(recipe.ordered[3] as? SpecialistHead)\n        #expect(!preview.settings.admission && preview.negatives == .real(\"preview\"))\n        let human = SpecialistHead(.human)\n        #expect(human.regularization(C: 2).settings.C == 2 && human.settings.C == 0.5)\n        let data = try JSONEncoder().encode(recipe)\n        #expect(try JSONDecoder().decode(TrainingRecipe.self, from: data) == recipe)\n        let text = String(decoding: data, as: UTF8.self)\n        #expect(text.contains(\"\\\"kind\\\":\\\"camera\\\"\") && text.contains(\"\\\"kind\\\":\\\"specialist\\\"\") && text.contains(\"\\\"kind\\\":\\\"combiner\\\"\"))\n        #expect(throws: (any Error).self, \"a recipe.json naming a kind this build does not train\") {\n            try JSONDecoder().decode(TrainingRecipe.self, from: Data(#\"{\"id\":\"x\",\"members\":[{\"kind\":\"fusion\",\"member\":{}}]}\"#.utf8))\n        }\n    }\n\n    @Test(\"the shipped preset trains every member the store reproduces: the camera head from scratch, three heads, the preview head, the combiner\")\n    func shipped() throws {\n        let recipe = TrainingRecipe.shipped(id: \"s\")\n        #expect(recipe.ordered.map(\\.name) == [\"camera\", \"head:art\", \"head:blur\", \"head:human\", \"head:preview\", \"combiner\"])\n        let camera = try #require(recipe.ordered[0] as? CameraHead)\n        #expect(camera.settings.mode == .scratch(trees: 500, eta: 0.04))\n        #expect(HeadKind.flywheelCategories == [.art, .blur, .human])\n        #expect(TrainingRecipe.kindNames == [\"camera\", \"specialist\", \"combiner\"])\n    }\n\n    @Test(\"recipe.toml reads into the same recipe\")\n    func toml() throws {\n        let text = \"\"\"\n        id = \"weekly\"   # a comment\n        [camera]\n        mode = \"warm\"\n        add = 20\n        [heads]\n        kinds = [\"art\", \"preview\"]\n        [combiner]\n        reals_weight = 2.0\n        \"\"\"\n        let recipe = try RecipeFile.parse(text)\n        let expected = TrainingRecipe(id: \"weekly\") {\n            CameraHead().warmStart(add: 20, eta: 0.03)\n            SpecialistHead(.art)\n            SpecialistHead(.preview)\n            Combiner().realsWeight(2)\n        }\n        #expect(recipe == expected)\n        let scratch = try RecipeFile.parse(\"id = \\\"s\\\"\\n[camera]\\nmode = \\\"scratch\\\"\\ntrees = 50\\ndepth = 7\")\n        #expect(scratch == TrainingRecipe(id: \"s\") { CameraHead().scratch(trees: 50, eta: 0.04).depth(7) })\n        #expect(throws: VeilGardeFailure.self) { try RecipeFile.parse(\"id = \\\"x\\\"\\n[camera]\\ncolour = 1\") }\n        #expect(throws: VeilGardeFailure.self) { try RecipeFile.parse(\"id = \\\"x\\\"\\n[optimizer]\\nlr = 1\") }\n        #expect(throws: VeilGardeFailure.self) { try RecipeFile.parse(\"[heads]\\nkinds = [\\\"art\\\"]\") }\n        #expect(throws: VeilGardeFailure.self) { try RecipeFile.parse(\"id = \\\"x\\\"\\n[heads]\\nkinds = [\\\"faces\\\"]\") }\n        #expect(throws: VeilGardeFailure.self) { try RecipeFile.parse(\"id = \\\"x\\\"\\n[camera]\\ndepth = 40\") }\n        #expect(throws: VeilGardeFailure.self) { try RecipeFile.parse(\"id = \\\"x\\\"\\n[fusion]\\nmode = \\\"warm\\\"\") }\n        #expect(throws: VeilGardeFailure.self) { try RecipeFile.parse(\"id = \\\"x\\\"\\n[camera]\\ncolumns = \\\"dino_fusion,cap\\\"\") }\n        #expect(throws: VeilGardeFailure.self) { try RecipeFile.parse(\"id = \\\"x\\\"\\n[combiner]\\nout_of_fold = 5\") }\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/SplitTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,43]],"header":{"lines":[1,7],"target":"VeilGardeTrainingTests","what":[6,6],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1469,"scopes":[["S","SplitTests",null,"",14,15,[15,18],43,null,-1,0,"a"],["f","raSplit",[],"",16,17,[17,26],24,null,0,0,"a"],["f","oneClassFallback",[],"",26,27,[27,28],42,null,0,0,"a"]],"old":"","new":"//\n//  SplitTests.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The head split, draw for draw (source-disjoint with ≥ 4 sources, by id otherwise).\n//\n\nimport Foundation\nimport Testing\nimport VeilGardeCore\n@testable import VeilGardeTraining\n\n@Suite(\"Splits\")\nstruct SplitTests {\n    @Test(\"HeadSplit.heads equals atlas_heads_store.py's split\")\n    func raSplit() throws {\n        let cases = try Fixture.json(\"head_split.json\")[\"cases\"] as! [[String: Any]]\n        for c in cases {\n            let split = HeadSplit.heads(ids: c[\"ids\"] as! [String], sources: c[\"sources\"] as! [String])\n            #expect(split.isTest == (c[\"test\"] as! [Bool]))\n            #expect(split.basis.rawValue == c[\"basis\"] as! String)\n        }\n    }\n\n    @Test(\"a source split that leaves a class out falls back to the id split\")\n    func oneClassFallback() {\n        // Every generated row comes from one source; that source is not among the test sources.\n        let sources = [\"civitai\", \"a\", \"b\", \"c\", \"d\", \"e\", \"f\", \"g\"]\n        var ids: [String] = [], src: [String] = [], labels: [Int] = []\n        for k in 0..<400 { ids.append(\"id\\(k)\"); src.append(sources[k % sources.count]); labels.append(src.last == \"civitai\" ? 1 : 0) }\n        let plain = HeadSplit.heads(ids: ids, sources: src)\n        let checked = HeadSplit.heads(ids: ids, sources: src, labels: labels)\n        let testHoldsBoth = Set(zip(labels, checked.isTest).filter { $0.1 }.map(\\.0)).count == 2\n        if Set(zip(labels, plain.isTest).filter { $0.1 }.map(\\.0)).count == 2 {\n            #expect(checked == plain)\n        } else {\n            #expect(checked.basis == .idsAfterOneClassSources)\n            #expect(testHoldsBoth)\n            #expect(checked.isTest == HeadSplit.byIDs(ids).isTest)\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeTrainingTests/Synthetic.swift","status":"added","lang":"swift","hunks":[[1,0,1,78]],"header":{"lines":[1,9],"target":"VeilGardeTrainingTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[[37,"The store"]],"first":1472,"scopes":[["S","SyntheticArea",null,"",15,15,[15,21],78,null,-1,0,"a"],["f","make",[],"static",21,21,[21,47],33,null,0,0,"a"],["f","remove",[],"",35,35,[35,18],35,null,0,8,"a"],["f","writeStore",["_"],"static",39,39,[39,52],77,null,0,0,"a"],["f","gauss",[],"",41,41,[41,30],44,null,3,4,"a"]],"old":"","new":"//\n//  Synthetic.swift\n//  VeilGardeTrainingTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: A throwaway work area for the engine's tests: a copy of the shipped bundle as the parent and\n//        a seeded features-only store with every category the recipes read, so a full recipe trains\n//        without the GPU or a single image.\n//\n\nimport Foundation\nimport VeilGardeCore\n@testable import VeilGardeTraining\n\nstruct SyntheticArea {\n    let root: URL\n    let area: WorkArea\n    let parent: URL\n    let store: URL\n\n    static func make() throws -> SyntheticArea {\n        let root = FileManager.default.temporaryDirectory.appendingPathComponent(\"vg-engine-\\(UUID().uuidString)\", isDirectory: true)\n        let fm = FileManager.default\n        try fm.createDirectory(at: root, withIntermediateDirectories: true)\n        // The parent: the shipped bundle's resources, copied.\n        let parent = root.appendingPathComponent(\"parent\", isDirectory: true)\n        try fm.copyItem(at: Fixture.resources, to: parent)\n        let area = WorkArea(root: root.appendingPathComponent(\"area\", isDirectory: true))\n        let store = area.root.appendingPathComponent(\"store/shards\", isDirectory: true)\n        try fm.createDirectory(at: store, withIntermediateDirectories: true)\n        try writeStore(store)\n        return SyntheticArea(root: root, area: area, parent: parent, store: store)\n    }\n\n    func remove() { try? FileManager.default.removeItem(at: root) }\n\n    // MARK: The store\n\n    static func writeStore(_ directory: URL) throws {\n        var rng = SplitMix64(seed: 7)\n        func gauss() -> Float {\n            let u = max(1e-12, rng.unit()), v = rng.unit()\n            return Float((-2 * log(u)).squareRoot() * cos(2 * .pi * v))\n        }\n        let sources = [\"civitai\", \"commons_native\", \"wikimedia\", \"inat\", \"hf_faces\", \"openverse\", \"mj_v6\"]\n        let plan: [(category: String, label: Int, count: Int)] = [\n            (\"art\", 1, 150), (\"art\", 0, 100), (\"blur\", 1, 100), (\"blur\", 0, 80), (\"human\", 1, 120), (\"human\", 0, 200),\n            (\"cgi\", 1, 80), (\"cgi\", 0, 60), (\"preview\", 1, 60), (\"preview\", 0, 60), (\"photo\", 0, 220),\n        ]\n        let categoryIndex = [\"art\": 0, \"blur\": 1, \"human\": 2, \"cgi\": 3, \"preview\": 4, \"photo\": 5]\n        for (shardName, newGen) in [(\"base_a\", false), (\"scrape_20260101\", true)] {\n            var rows: [FeatureRow] = []\n            var columns: [FeatureColumn: [Float]] = Dictionary(uniqueKeysWithValues: FeatureColumn.allCases.map { ($0, [Float]()) })\n            var serial = 0\n            for p in plan where !newGen || p.label == 1 {\n                let n = newGen ? p.count / 3 : p.count\n                for _ in 0..<n {\n                    serial += 1\n                    let id = ContentHash.sha1Hex(Data(\"\\(shardName)-\\(serial)\".utf8))\n                    let golden = !newGen && p.category == \"photo\" && serial % 7 == 0\n                    let path = golden && serial % 21 == 0 ? \"/pools/bsky/\\(serial).jpg\" : \"/pools/\\(p.category)/\\(serial).jpg\"\n                    rows.append(FeatureRow(id: id, path: path, label: p.label, category: p.category, source: sources[serial % sources.count],\n                                           nsfw: serial % 53 == 0, golden: golden))\n                    let c = categoryIndex[p.category]!\n                    var norm = (0..<384).map { _ in gauss() }\n                    if p.label == 1 { for j in (c * 10)..<(c * 10 + 10) { norm[j] += 1.6 } }\n                    var fusion = (0..<384).map { _ in gauss() }\n                    if p.label == 1 { for j in 0..<12 { fusion[j] += 1.0 } }\n                    columns[.dinoNorm]! += norm\n                    columns[.dinoFusion]! += fusion\n                    let present: Float = p.label == 0 && serial % 3 == 0 ? 1 : 0\n                    columns[.cap]! += [Float(rng.unit() * 60), 1, present, 2000, Float(rng.unit() * 10), 0.5, 0.5, 0.5, 0]\n                }\n            }\n            try FeatureShard(name: shardName, rows: rows, columns: columns).write(to: directory)\n        }\n    }\n}\n"}]};
